const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const { BoardRoomManager } = require('../services/boardRoom');
const { authenticateSessionCookie, canAccessDocument } = require('../auth/session');

const app = express();
const server = http.createServer(app);

const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', async (req, socket, head) => {
  const user = await authenticateSessionCookie(req);
  if (!user) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  const rawProtocols = req.headers['sec-websocket-protocol'] || '';
  const match = rawProtocols.match(/canvas\.doc\.([a-zA-Z0-9_-]+)/);

  if (!match) {
    socket.destroy();
    return;
  }

  const documentId = match[1];
  const hasAccess = await canAccessDocument(user.id, documentId);
  if (!hasAccess) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(req, socket, head, (ws) => {
    BoardRoomManager.joinRoom(documentId, ws);
  });
});

server.listen(3001);
